PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,folder TEXT UNIQUE NOT NULL,profile_json TEXT NOT NULL,instructions TEXT NOT NULL,present INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS episodes(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id),folder TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unverified',present INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS blobs(sha256 TEXT PRIMARY KEY,bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id),episode_id TEXT REFERENCES episodes(id),path TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,sha256 TEXT NOT NULL REFERENCES blobs(sha256),bytes INTEGER NOT NULL,mtime_ns INTEGER NOT NULL,present INTEGER NOT NULL DEFAULT 1,scope TEXT NOT NULL,rights TEXT NOT NULL DEFAULT 'unknown');
CREATE INDEX IF NOT EXISTS assets_channel_kind ON assets(channel_id,kind);
CREATE TABLE IF NOT EXISTS documents(asset_id TEXT PRIMARY KEY REFERENCES assets(id),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS annotations(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id),episode_id TEXT REFERENCES episodes(id),kind TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id),episode_id TEXT NOT NULL REFERENCES episodes(id),platform TEXT NOT NULL,account_id TEXT NOT NULL,format TEXT NOT NULL,organic INTEGER NOT NULL,published_at TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metric_snapshots(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id),observed_at TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id),observed_at TEXT NOT NULL,payload_json TEXT NOT NULL);
